// Get the repo's GitHub remote URL
repo, err := strategy.OpenRepository(ctx)
if err != nil {
	cmd.SilenceUsage = true
	fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run this command from within a git repository.")
	return NewSilentError(err)
}
defer repo.Close()

remote, err := repo.Remote("origin")
if err != nil {
	return fmt.Errorf("could not find 'origin' remote: %w", err)
}
urls := remote.Config().URLs
if len(urls) == 0 {
	return errors.New("origin remote has no URLs configured")
}

owner, repoName, err := search.ParseGitHubRemote(urls[0])
if err != nil {
	return fmt.Errorf("parsing remote URL: %w", err)
}

// Semantic search goes to the v4 query-serve path (entire-api
// cell gateway) via newSemanticSearcher, which fans out across
// cells and mints per-cell identity tokens itself (ENT-1055).
searcher := newSemanticSearcher(insecureHTTPAuth)

searchCfg := search.Config{
	Owner:    owner,
	Repo:     repoName,
	Repos:    repos,
	AllRepos: allRepos,
	Query:    query,
	Limit:    limitFlag,
	Page:     pageFlag,
	Author:   authorFlag,
	Date:     dateFlag,
	Branch:   branchFlag,
}

// Use wildcard query when only filters are provided
if query == "" && searchCfg.HasFilters() {
	searchCfg.Query = search.WildcardQuery
}

// No query provided + interactive = open TUI with search bar focused
if query == "" && !searchCfg.HasFilters() {
	searchCfg.Limit = search.DefaultLimit
	styles := newStatusStyles(w)
	model := newSearchModel(nil, "", 0, searchCfg, styles, buildCodeSearchOpts(ctx, owner, repoName, nil, false, insecureHTTPAuth))
	model.semanticSearch = searcher
	model.mode = modeSearch
	model.input.Focus()
	model.codeLoading = false // don't fetch until a query is entered
	p := tea.NewProgram(model)
	if _, err := p.Run(); err != nil {
		return fmt.Errorf("TUI error: %w", err)
	}
	return nil
}

// Fetch a full page (DefaultLimit, matching the web UI) up front and
// paginate client-side for all output modes; the requested --limit
// only controls the client-side page size.
requestedLimit := searchCfg.Limit
requestedPage := searchCfg.Page
searchCfg.Limit = search.DefaultLimit
searchCfg.Page = 0 // let API default to page 1

resp, err := searcher(ctx, searchCfg)
if err != nil {
	return fmt.Errorf("search failed: %w", err)
}
for _, warning := range resp.Warnings {
	fmt.Fprintln(cmd.ErrOrStderr(), "warning: "+warning)
}

// JSON output: explicit flag or piped/redirected stdout
if jsonOutput || !isTerminal {
	searchID := newSearchID()
	mode := "json"
	var served int
	var writeErr error
	if compactOutput {
		mode = "compact"
		served, writeErr = writeSearchCompactJSON(w, resp, requestedLimit, requestedPage, searchID, owner+"/"+repoName)
	} else {
		served, writeErr = writeSearchJSON(w, resp, requestedLimit, requestedPage, searchID)
	}
	if writeErr != nil {
		return writeErr
	}
	emitSearchPerformed(ctx, searchID, searchCfg.Query, mode, served, len(resp.Results), requestedPage, requestedLimit)
	return nil
}

styles := newStatusStyles(w)

// Accessible mode: static table

Checkpoint detail view shows:
  - Author of the checkpoint
  - Associated git commits that reference the checkpoint
  - Prompts and responses from the session

Note: --session filters the list view; the positional arg, --commit, and --checkpoint are mutually exclusive.`,
		Args: func(_ *cobra.Command, args []string) error {
			if len(args) > 1 {
				return fmt.Errorf("accepts at most 1 argument (checkpoint ID or commit SHA), received %d\nHint: use --session to filter the list view, or pass a single checkpoint ID / commit SHA", len(args))
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			// Attach the --search-id attribution (from a compact search hint)
			// to the context so every explain path's telemetry emit can read
			// it without threading a parameter through the call chains.
			cmd.SetContext(withExplainSearchHit(cmd.Context(), searchIDFlag))

			// Check if Entire is disabled
			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
				return nil
			}

			// Only initialize logging when inside a git worktree to avoid
			// creating .entire/logs/ in arbitrary directories.
			if _, err := paths.WorktreeRoot(cmd.Context()); err == nil {
				logging.SetLogLevelGetter(GetLogLevel)
				if err := logging.Init(cmd.Context(), ""); err == nil {
					defer logging.Close()
				}
			}

			// Positional arg is mutually exclusive with --checkpoint, --commit, --session
			var positional string
			if len(args) > 0 {
				positional = args[0]
				if checkpointFlag != "" || commitFlag != "" || sessionFlag != "" {
					return errors.New("cannot combine positional argument with --checkpoint, --commit, or --session")
				}
			}

			if err := validateExplainFlagCombinations(cmd, explainFlagValues{
				checkpoint:            checkpointFlag,
				commit:                commitFlag,
				repo:                  repoFlag,
				generate:              generateFlag,
				force:                 forceFlag,
				rawTranscript:         rawTranscriptFlag,
				transcript:            transcriptFlag,
				json:                  jsonFlag,
				sessionIndex:          sessionIndex,
				listLimit:             listLimit,
				summaryTimeoutSeconds: summaryTimeoutSecondsFlag,
			}, positional); err != nil {
				return err
			}

			// Cross-repo: read the foreign checkpoint from its repo's cell and
			// render it with the same formatters as a local one. Routed before
			// the local pipelines because none of their git-backed resolution
			// (commit walks, prefix matching, blob prefetch) applies to a repo
			// that isn't checked out here.
			if repoFlag != "" {
				target := positional
				if target == "" {
					target = checkpointFlag
				}
				if !explainRepoTargetsCurrentRepo(cmd.Context(), repoFlag) {
					// Past flag parsing every failure is a runtime one
					// (network, auth, missing checkpoint), not a usage
					// mistake — don't dump usage text on it.
					cmd.SilenceUsage = true
					return runCrossRepoExplain(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), crossRepoExplainOptions{
						repoFlag:      repoFlag,
						target:        target,
						json:          jsonFlag,
						transcript:    transcriptFlag,
						rawTranscript: rawTranscriptFlag,
						sessionIndex:  crossRepoExplainSessionIndex(cmd.Flags().Changed("session-index"), sessionIndex),
						verbose:       !shortFlag,
						full:          fullFlag,
						noPager:       noPagerFlag,
						insecureHTTP:  insecureHTTPFlag,
					})
				}
				// --repo naming the current repo is a no-op: the local path is
				// faster and can also read checkpoints that aren't pushed yet.
			}

			// Export modes — emit machine-readable output and skip the prose pipeline.
			// --raw-transcript also routes here when --session-index is explicit; the
			// legacy raw-transcript path (with spinner + prefetch) handles the default
			// case where the caller wants the latest session.
			rawWithSessionIndex := rawTranscriptFlag && cmd.Flags().Changed("session-index")
			if jsonFlag || transcriptFlag || rawWithSessionIndex {
				return runExplainExport(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), explainExportOptions{
					sessionFilter:  sessionFlag,
					commitRef:      commitFlag,
					checkpointFlag: checkpointFlag,
					target:         positional,
					json:           jsonFlag,
					transcript:     transcriptFlag,
					rawTranscript:  rawTranscriptFlag,
					sessionIndex:   sessionIndex,
					listLimit:      listLimit,
				})
			}

			// Convert short flag to verbose (verbose = !short)
			verbose := !shortFlag
			return runExplain(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionFlag, commitFlag, checkpointFlag, positional, noPagerFlag, verbose, fullFlag, rawTranscriptFlag, generateFlag, forceFlag, searchAllFlag, summaryTimeoutSecondsFlag)
		},
	}

	cmd.Flags().StringVar(&sessionFlag, "session", "", "Filter checkpoints by session ID (or prefix)")
	cmd.Flags().StringVar(&commitFlag, "commit", "", "Explain a specific commit (SHA or ref, \"commit-ish\")")
	cmd.Flags().StringVarP(&checkpointFlag, "checkpoint", "c", "", "Explain a specific checkpoint (ID or prefix)")
	cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
	cmd.Flags().BoolVarP(&shortFlag, "short", "s", false, "Show summary only (omit prompts and files)")
	cmd.Flags().BoolVar(&fullFlag, "full", false, "Show full parsed transcript (all prompts/responses)")
	cmd.Flags().BoolVar(&rawTranscriptFlag, "raw-transcript", false, "Show raw transcript file (JSONL format)")
	cmd.Flags().BoolVar(&generateFlag, "generate", false, "Generate an AI summary for the checkpoint")
	cmd.Flags().BoolVar(&forceFlag, "force", false, "Regenerate summary even if one already exists (requires --generate)")
	cmd.Flags().BoolVar(&searchAllFlag, "search-all", false, "Search all commits (no branch/depth limit, may be slow)")
	cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output metadata as JSON (no transcript bytes)")
	cmd.Flags().BoolVar(&transcriptFlag, "transcript", false, "Stream stored checkpoint transcript bytes to stdout")
	cmd.Flags().IntVar(&sessionIndex, "session-index", -1, "Session index within a multi-session checkpoint (0-based, defaults to latest)")
	cmd.Flags().IntVar(&listLimit, "limit", 0, "Cap the list view at N checkpoints (default: 100). Only meaningful with --json.")
	cmd.Flags().StringVar(&repoFlag, "repo", "", "Explain a checkpoint owned by another repo (owner/name or gh/owner/name), read from that repo's Entire API")
	cmd.Flags().BoolVar(&insecureHTTPFlag, "insecure-http-auth", false, "Allow plain-HTTP auth for --repo (local dev only)")
	cmd.Flags().IntVar(&summaryTimeoutSecondsFlag, "summary-timeout-seconds", 0, "Hard deadline in seconds for --generate summary generation; overrides summary_timeout_seconds setting. 0 = use setting; if setting is also unset or 0, no automatic deadline applies.")
