88	// resolveExplainCheckpointID resolves a target to a fully-qualified checkpoint
89	// ID. Resolution order matches the prose explain command:
90	//
91	//  1. --commit <ref>  → resolve as a git commit, read Entire-Checkpoint
92	//     trailer; remote metadata fetch-on-miss when the trailer points at
93	//     an unknown checkpoint.
94	//  2. --checkpoint <id> or positional checkpoint-id-prefix → match against
95	//     committed checkpoints, with remote metadata fetch-on-miss.
96	//  3. Positional that fails as a checkpoint prefix falls back to commit-ref
97	//     resolution (mirrors runExplainAuto).
98	func resolveExplainCheckpointID(ctx context.Context, errW io.Writer, opts explainExportOptions) (id.CheckpointID, *explainCheckpointLookup, error) {
99		if opts.commitRef != "" {
100			return resolveCheckpointFromCommitRef(ctx, errW, opts.commitRef)
101		}
102	
103		prefix := opts.checkpointFlag
104		if prefix == "" {
105			prefix = opts.target
106		}
107		if prefix == "" {
108			return id.CheckpointID(""), nil, errors.New("missing checkpoint target")
109		}
110	
111		lookup, lookupErr := newExplainCheckpointLookup(ctx)
112		if lookupErr != nil {
113			return id.CheckpointID(""), nil, lookupErr
114		}
115	
116		matches, resolvedLookup := matchCheckpointPrefixWithRemoteFallback(ctx, errW, lookup, prefix)
117		if resolvedLookup != lookup {
118			_ = lookup.Close()
119			lookup = resolvedLookup
120		}
121		switch len(matches) {
122		case 1:
123			return matches[0], lookup, nil
124		case 0:
125			// If the user passed a positional target (not --checkpoint), give it
126			// one more shot as a commit ref before failing — mirrors the prose
127			// runExplainAuto behavior so `--json <commit-sha>` works.
128			if opts.target != "" && opts.checkpointFlag == "" {
129				cpID, freshLookup, commitErr := resolveCheckpointFromCommitRef(ctx, errW, opts.target)
130				if commitErr == nil {
131					_ = lookup.Close()
132					return cpID, freshLookup, nil
133				}
134				// Only "the target isn't a commit at all" is a genuine miss that
135				// keeps the checkpoint-not-found report below. Everything else —
136				// unreadable commit, missing trailer, ambiguous ref, repo or
137				// lookup failure — reflects a real failure, not a miss; masking
138				// those as not-found is this path's variant of the conflation
139				// PR #1812 fixes for the prose path in runExplainAuto (this
140				// path's fix: issue #1814).
141				if !errors.Is(commitErr, errExportTargetNotCommit) {
142					if freshLookup != nil {
143						// Defensive: resolveCheckpointFromCommitRef documents a
144						// nil lookup on error, but a leak here would be silent.
145						_ = freshLookup.Close()
146					}
147					return id.CheckpointID(""), lookup, commitErr
148				}
149			}
150			return id.CheckpointID(""), lookup, fmt.Errorf("%w: %s", checkpoint.ErrCheckpointNotFound, prefix)
151		default:
152			ids := make([]string, len(matches))
153			for i, m := range matches {
154				ids[i] = m.String()
155			}
156			return id.CheckpointID(""), lookup, fmt.Errorf("%w: %s matches %d checkpoints (%s)", errAmbiguousCommitPrefix, prefix, len(matches), strings.Join(ids, ", "))
157		}
158	}
159	
